#!/usr/bin/env node
// Generates the README's server table from each server's own tool list.
//
//   servers.json     the map: which servers the suite lists, and where each
//                    one's tool list lives (hand-maintained)
//   tool-lists.json  each counted server's tool names, read from its latest
//                    npm release (generated by `update`)
//   README.md        the blocks between <!-- server-table:start/end --> and
//                    <!-- server-profiles:start/end --> (generated by `update`)
//
// Commands:
//   node scripts/server-table.js check            offline: README blocks match tool-lists.json
//   node scripts/server-table.js check --remote   also: tool-lists.json matches each latest release
//   node scripts/server-table.js update           refresh tool-lists.json from npm + GitHub, rewrite the README blocks
//
// A tool list is read as text and parsed; no server code is installed or run.

const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.join(__dirname, "..");
const BLOCKS = ["server-table", "server-profiles"];
const GENERATED_NOTE = "<!-- Generated by `npm run table:update` from servers.json and tool-lists.json. Do not edit by hand. -->";

// --- parsing -----------------------------------------------------------------

/**
 * Tool names in a TypeScript `export const tools = [ {...}, ... ]` array,
 * in source order. Reads the text only. Each element must be an object
 * literal with a string `name`; a spread or a bare identifier can't be
 * counted from the text, so it is an error rather than a guess.
 */
function parseTsToolNames(source) {
  const decl = /export\s+const\s+tools\b[^=]*=\s*\[/.exec(source);
  if (!decl) throw new Error("no `export const tools = [` array found");
  let i = decl.index + decl[0].length;
  const n = source.length;
  const stack = ["["]; // openers; stack.length 1 = inside the array, 2 = inside a tool object
  const names = [];
  let current = null; // { name } for the tool object being read
  let expectKey = false; // inside a tool object, right after `{` or `,`

  const fail = (msg) => {
    const line = source.slice(0, i).split("\n").length;
    throw new Error(`${msg} (line ${line})`);
  };

  function skipString(quote) {
    // i is at the opening quote
    i++;
    while (i < n) {
      const c = source[i];
      if (c === "\\") {
        i += 2;
        continue;
      }
      if (quote === "`" && c === "$" && source[i + 1] === "{") {
        i += 2;
        skipCodeUntilClose();
        continue;
      }
      if (c === quote) {
        i++;
        return;
      }
      i++;
    }
    fail("unterminated string");
  }

  function readString() {
    const quote = source[i];
    const start = i + 1;
    skipString(quote);
    return source.slice(start, i - 1);
  }

  // Skip a ${ ... } expression inside a template literal, strings included.
  function skipCodeUntilClose() {
    let depth = 1;
    while (i < n && depth > 0) {
      const c = source[i];
      if (c === '"' || c === "'" || c === "`") {
        skipString(c);
        continue;
      }
      if (c === "{") depth++;
      if (c === "}") depth--;
      i++;
    }
  }

  function skipComment() {
    if (source.startsWith("//", i)) {
      const end = source.indexOf("\n", i);
      i = end === -1 ? n : end;
      return true;
    }
    if (source.startsWith("/*", i)) {
      const end = source.indexOf("*/", i + 2);
      if (end === -1) fail("unterminated comment");
      i = end + 2;
      return true;
    }
    return false;
  }

  while (i < n) {
    const c = source[i];
    if (/\s/.test(c)) {
      i++;
      continue;
    }
    if (c === "/" && skipComment()) continue;
    const depth = stack.length;

    if (depth === 1) {
      // Directly inside the tools array: only `{`, `,` or the closing `]`.
      if (c === "]") return finish();
      if (c === ",") {
        i++;
        continue;
      }
      if (c === "{") {
        stack.push("{");
        current = { name: null };
        expectKey = true;
        i++;
        continue;
      }
      if (source.startsWith("...", i)) fail("tools array holds a spread; its tools can't be counted from the text");
      fail("tools array element is not an object literal");
    }

    if (depth === 2 && expectKey) {
      // A key of the tool object itself.
      let key = null;
      if (c === '"' || c === "'") key = readString();
      else {
        const m = /^[A-Za-z_$][\w$]*/.exec(source.slice(i, i + 64));
        if (m) {
          key = m[0];
          i += key.length;
        }
      }
      expectKey = false;
      if (key === "name") {
        while (i < n && /\s/.test(source[i])) i++;
        if (source[i] !== ":") fail("tool `name` is not a key: value pair");
        i++;
        while (i < n && /\s/.test(source[i])) i++;
        if (source[i] !== '"' && source[i] !== "'") fail("tool name is not a string literal");
        current.name = readString();
      }
      if (key !== null) continue;
    }

    if (c === '"' || c === "'" || c === "`") {
      skipString(c);
      continue;
    }
    if (c === "{" || c === "[" || c === "(") {
      stack.push(c);
      i++;
      continue;
    }
    if (c === "}" || c === "]" || c === ")") {
      stack.pop();
      if (depth === 2) {
        if (!current || !current.name) fail("tool object has no name");
        names.push(current.name);
        current = null;
      }
      i++;
      continue;
    }
    if (c === "," && depth === 2) expectKey = true;
    i++;
  }
  fail("tools array is not closed");

  function finish() {
    const seen = new Set();
    for (const name of names) {
      if (seen.has(name)) throw new Error(`duplicate tool name ${name}`);
      seen.add(name);
    }
    return names;
  }
}

// --- rendering ---------------------------------------------------------------

function countedServers(servers) {
  return servers.servers.filter((s) => s.tools);
}

function tokensLabel(tokens) {
  return `~${Math.round(tokens / 1000)}K tokens`;
}

function repoUrl(s) {
  return `https://github.com/${s.repo}`;
}

function installCommand(s) {
  return s.registry === "pypi" ? `pip install ${s.package}` : `npm install ${s.package}`;
}

/** Markdown for each generated block, keyed by block name. */
function renderBlocks(servers, toolLists) {
  const perTool = servers.tokensPerTool;
  const counted = countedServers(servers);

  const header = [
    "| Server | Platform | Tools | ~Context cost | Release | Install | Setup | What it does |",
    "|--------|----------|-------|---------------|---------|---------|-------|--------------|",
  ];
  const rows = servers.servers.map((s) => {
    const list = s.tools ? toolLists[s.package] : null;
    const toolsCell = list ? `[${list.tools.length}](${repoUrl(s)}/blob/${list.commit}/${list.source})` : "not counted";
    const costCell = list ? tokensLabel(list.tools.length * perTool) : "—";
    const releaseCell = list ? list.version : "—";
    const setupCell = s.setup ? `[setup](${s.setup})` : `[README](${repoUrl(s)}#readme)`;
    return `| [${s.package}](${repoUrl(s)}) | ${s.platform} | ${toolsCell} | ${costCell} | ${releaseCell} | \`${installCommand(s)}\` | ${setupCell} | ${s.summary} |`;
  });
  const total = counted.reduce((sum, s) => sum + (toolLists[s.package] ? toolLists[s.package].tools.length : 0), 0);
  const notes = [
    `**${total} tools** across the ${counted.length} first-party servers, counted from each one's latest npm release. Context cost assumes ~${perTool} tokens per tool schema.`,
    ...servers.servers.filter((s) => !s.tools).map((s) => `${s.package} is not counted: ${s.notCountedReason}.`),
  ];
  const table = [GENERATED_NOTE, "", ...header, ...rows, "", ...notes.flatMap((l) => [l, ""])].join("\n").trimEnd();

  const profileRows = servers.profiles.map((p) => {
    const members = p.servers === "all" ? servers.servers.map((s) => s.package) : p.servers;
    const byPackage = new Map(servers.servers.map((s) => [s.package, s]));
    let tokens = 0;
    const uncounted = [];
    for (const pkg of members) {
      const s = byPackage.get(pkg);
      if (!s) throw new Error(`profile "${p.name}" names unknown server ${pkg}`);
      const list = s.tools ? toolLists[pkg] : null;
      if (list) tokens += list.tools.length * perTool;
      else uncounted.push(pkg);
    }
    const label = p.servers === "all" ? `all ${members.length} servers` : members.join(" + ");
    const cost = [tokensLabel(tokens), ...uncounted].join(" + ");
    return `| ${p.name} | ${label} | ${cost} |`;
  });
  const profiles = [GENERATED_NOTE, "", "| Profile | Servers | ~Context cost |", "|---------|---------|---------------|", ...profileRows].join("\n");

  return { "server-table": table, "server-profiles": profiles };
}

// --- README blocks -------------------------------------------------------------

function markers(name) {
  return { start: `<!-- ${name}:start -->`, end: `<!-- ${name}:end -->` };
}

function findBlock(readme, name) {
  const { start, end } = markers(name);
  const a = readme.indexOf(start);
  const b = readme.indexOf(end);
  if (a === -1 || b === -1 || b < a) return null;
  if (readme.indexOf(start, a + 1) !== -1 || readme.indexOf(end, b + 1) !== -1) return null;
  return { from: a + start.length, to: b };
}

/** README with each named block's body replaced; throws if a block's markers are missing. */
function replaceBlocks(readme, blocks) {
  let out = readme;
  for (const name of Object.keys(blocks)) {
    const at = findBlock(out, name);
    if (!at) throw new Error(`README has no single ${markers(name).start} ... ${markers(name).end} pair`);
    out = out.slice(0, at.from) + "\n" + blocks[name] + "\n" + out.slice(at.to);
  }
  return out;
}

/** Problems that keep the README from matching the tool lists; [] when it does. */
function checkReadme(readme, servers, toolLists) {
  const problems = [];
  const counted = countedServers(servers).map((s) => s.package);
  for (const pkg of counted) {
    if (!toolLists[pkg]) problems.push(`${pkg} is counted in servers.json but has no tool list in tool-lists.json`);
  }
  for (const pkg of Object.keys(toolLists)) {
    if (!counted.includes(pkg)) problems.push(`tool-lists.json has ${pkg}, which servers.json does not count`);
  }
  if (problems.length) return problems;

  const expected = renderBlocks(servers, toolLists);
  for (const name of BLOCKS) {
    const at = findBlock(readme, name);
    if (!at) {
      problems.push(`${name}: README has no single ${markers(name).start} ... ${markers(name).end} marker pair`);
      continue;
    }
    const actual = readme.slice(at.from, at.to).trim();
    if (actual !== expected[name].trim()) {
      problems.push(`${name}: README block differs from what servers.json and tool-lists.json generate`);
    }
  }
  return problems;
}

// --- fetching ------------------------------------------------------------------

function normalizeRepo(url) {
  const m = /github\.com[/:]([^/]+\/[^/.#]+?)(?:\.git)?(?:[#/].*)?$/.exec(url || "");
  return m ? m[1].toLowerCase() : null;
}

/**
 * Tool lists for every counted server, read at the commit its latest npm
 * release was published from (the registry's gitHead). fetchJson/fetchText
 * are injected so tests never touch the network.
 */
async function fetchToolLists(servers, { fetchJson, fetchText }) {
  const out = {};
  for (const s of countedServers(servers)) {
    if (s.registry !== "npm") throw new Error(`${s.package}: only npm releases can be counted`);
    const meta = await fetchJson(`https://registry.npmjs.org/${s.package}/latest`);
    if (!meta || !meta.version) throw new Error(`${s.package}: npm registry returned no version`);
    if (!/^[0-9a-f]{40}$/.test(meta.gitHead || "")) {
      throw new Error(`${s.package}@${meta.version}: the release has no gitHead, so its tool list can't be pinned`);
    }
    const published = normalizeRepo(meta.repository && meta.repository.url);
    if (published !== s.repo.toLowerCase()) {
      throw new Error(`${s.package}: npm says its repository is ${published}, servers.json says ${s.repo}`);
    }
    const text = await fetchText(`https://raw.githubusercontent.com/${s.repo}/${meta.gitHead}/${s.tools.path}`);
    out[s.package] = { version: meta.version, commit: meta.gitHead, source: s.tools.path, tools: parseTsToolNames(text) };
  }
  return out;
}

/** One line per server whose release or tool names differ between two tool-list sets. */
function diffToolLists(before, after) {
  const lines = [];
  for (const pkg of [...new Set([...Object.keys(before), ...Object.keys(after)])].sort()) {
    const a = before[pkg];
    const b = after[pkg];
    if (!a || !b) {
      lines.push(`${pkg}: ${a ? "removed" : "added"}`);
      continue;
    }
    const added = b.tools.filter((t) => !a.tools.includes(t));
    const removed = a.tools.filter((t) => !b.tools.includes(t));
    if (a.version === b.version && a.commit === b.commit && !added.length && !removed.length) continue;
    const changes = [...added.map((t) => `+${t}`), ...removed.map((t) => `-${t}`)];
    lines.push(`${pkg} ${a.version} -> ${b.version}${changes.length ? `: ${changes.join(" ")}` : ""}`);
  }
  return lines;
}

// --- CLI -----------------------------------------------------------------------

async function httpGet(url) {
  const res = await fetch(url, { headers: { "User-Agent": "mcp-marketing-suite-server-table" } });
  if (!res.ok) throw new Error(`GET ${url}: HTTP ${res.status}`);
  return res;
}

const network = {
  fetchJson: async (url) => (await httpGet(url)).json(),
  fetchText: async (url) => (await httpGet(url)).text(),
};

function readJson(file) {
  return JSON.parse(fs.readFileSync(path.join(ROOT, file), "utf8"));
}

async function main(argv) {
  const [command, flag] = argv;
  const servers = readJson("servers.json");
  const readmePath = path.join(ROOT, "README.md");

  if (command === "update") {
    const lists = await fetchToolLists(servers, network);
    fs.writeFileSync(path.join(ROOT, "tool-lists.json"), JSON.stringify(lists, null, 2) + "\n");
    const readme = fs.readFileSync(readmePath, "utf8");
    fs.writeFileSync(readmePath, replaceBlocks(readme, renderBlocks(servers, lists)));
    console.log(`Updated tool-lists.json and README.md (${Object.keys(lists).length} servers).`);
    return 0;
  }

  if (command === "check") {
    const lists = readJson("tool-lists.json");
    const problems = checkReadme(fs.readFileSync(readmePath, "utf8"), servers, lists);
    if (flag === "--remote") {
      const latest = await fetchToolLists(servers, network);
      for (const line of diffToolLists(lists, latest)) problems.push(`tool-lists.json is behind the latest release: ${line}`);
    }
    if (problems.length) {
      for (const p of problems) console.error(`  ✗  ${p}`);
      console.error("\nRun `npm run table:update` and commit tool-lists.json and README.md.");
      return 1;
    }
    console.log(`  ✓  README server table matches the tool lists${flag === "--remote" ? " and each server's latest release" : ""}.`);
    return 0;
  }

  console.error("usage: server-table.js check [--remote] | update");
  return 2;
}

if (require.main === module) {
  main(process.argv.slice(2)).then(
    (code) => process.exit(code),
    (err) => {
      console.error(`server-table: ${err.message}`);
      process.exit(1);
    },
  );
}

module.exports = { parseTsToolNames, renderBlocks, replaceBlocks, checkReadme, fetchToolLists, diffToolLists };
